  /* v0.148.0 — the AI site links in «المساعد الذكي»: one shape, so one helper */
  function aiLink(id, name, host, ar, en) {
    return t(id, 'ai', 0,
      name, 'اختصار بنقرة واحدة يفتح ' + name + ' — ' + ar + '.',
      ['انقر الأيقونة فيُفتح ' + host + ' في تبويب جديد.', 'تجدها في تصنيف «المساعد الذكي» بعد «مساعد بروف»، وتصل إليها أيضًا بـ Alt+K ثم حرف التصنيف ثم حرف الأداة.'],
      name, 'A one-click shortcut that opens ' + name + ' — ' + en + '.',
      ['Click the icon: ' + host + ' opens in a new tab.', 'It sits in the «AI assistant» category after «Prof assistant», and is also reachable with Alt+K, then the category letter, then the tool\'s letter.']);
  }

